function addressOrInvoke(need) {
  if (need.stable && need.addressable) return 'resource:' + need.uri;
  if (need.computed || need.live || need.acts) return 'tool:' + need.tool;
  return 'resource:' + (need.uri || 'unknown');
}
const cases = [
  [{ stable: true, addressable: true, uri: 'policy://returns/30-day' }, 'resource:policy://returns/30-day'],
  [{ computed: true, tool: 'price-quote' }, 'tool:price-quote'],
  [{ live: true, tool: 'lookup-order' }, 'tool:lookup-order'],
  [{ acts: true, tool: 'issue-refund' }, 'tool:issue-refund'],
];
let pass = 0;
for (const [need, expected] of cases) {
  const got = addressOrInvoke(need);
  if (got === expected) pass++;
  else console.log('MISS ' + JSON.stringify(need) + ' -> ' + got);
}
console.log(pass + '/' + cases.length + ' needs routed');

